@Test
    public void testLogicDeleteSql() {
        String wherePKColumns = SqlHelper.wherePKColumns(User.class);
        Assert.assertEquals("<where> AND id = #{id} AND is_valid = 1</where>", wherePKColumns);

        String whereAllIfColumns = SqlHelper.whereAllIfColumns(User.class, false);
        Pattern p1 = Pattern.compile("<if.*?</if>");
        Matcher m1 = p1.matcher(whereAllIfColumns);
        List<String> ifs = new ArrayList<String>();
        while (m1.find()) {
            ifs.add(m1.group());
        }
        Collections.sort(ifs);
        String remaining1 = p1.matcher(whereAllIfColumns).replaceAll("");
        StringBuilder sb1 = new StringBuilder();
        for (int i = 0; i < ifs.size(); i++) {
            sb1.append(ifs.get(i));
        }
        String normalizedWhereAllIf = remaining1 + " | " + sb1.toString();
        String expectedWhereAllIf = "<where> AND is_valid = 1</where> | <if test=\"id != null\"> AND id = #{id}</if><if test=\"username != null\"> AND username = #{username}</if>";
        Assert.assertEquals(expectedWhereAllIf, normalizedWhereAllIf);

        String isLogicDeletedColumn = SqlHelper.whereLogicDelete(User.class, true);
        Assert.assertEquals(" AND is_valid = 0", isLogicDeletedColumn);

        String notLogicDeletedColumn = SqlHelper.whereLogicDelete(User.class, false);
        Assert.assertEquals(" AND is_valid = 1", notLogicDeletedColumn);

        String updateSetColumns = SqlHelper.updateSetColumns(User.class, null, false, false);
        Pattern p2 = Pattern.compile("<set>(.*?)</set>");
        Matcher m2 = p2.matcher(updateSetColumns);
        String normalizedUpdateSet = updateSetColumns;
        if (m2.find()) {
            String content = m2.group(1);
            String[] parts = content.split(",");
            List<String> nonEmpty = new ArrayList<String>();
            for (String part : parts) {
                if (!part.trim().isEmpty()) {
                    nonEmpty.add(part);
                }
            }
            Collections.sort(nonEmpty);
            StringBuilder sb2 = new StringBuilder();
            for (int i = 0; i < nonEmpty.size(); i++) {
                if (i > 0) sb2.append(",");
                sb2.append(nonEmpty.get(i));
            }
            normalizedUpdateSet = "<set>" + sb2.toString() + ",</set>";
        }
        String expectedUpdateSet = "<set>is_valid = 1,username = #{username},</set>";
        Assert.assertEquals(expectedUpdateSet, normalizedUpdateSet);
    }

