				if (node == null) return;
				org.w3c.dom.NodeList children = node.getChildNodes();
				java.util.List<org.w3c.dom.Node> childList = new java.util.ArrayList<>();
				for (int i = 0; i < children.getLength(); i++) {
					org.w3c.dom.Node child = children.item(i);
					if (child.getNodeType() == org.w3c.dom.Node.TEXT_NODE && child.getTextContent().trim().isEmpty()) {
						continue;
					}
					childList.add(child);
				}
				childList.sort((n1, n2) -> {
					if (n1.getNodeType() == org.w3c.dom.Node.ELEMENT_NODE && n2.getNodeType() == org.w3c.dom.Node.ELEMENT_NODE) {
						org.w3c.dom.Element e1 = (org.w3c.dom.Element) n1;
						org.w3c.dom.Element e2 = (org.w3c.dom.Element) n2;
