						String name2 = e2.getAttribute("name");
						if (name1 != null && !name1.isEmpty() && name2 != null && !name2.isEmpty()) {
							return name1.compareTo(name2);
						}
						String loc1 = e1.getAttribute("schemaLocation");
						String loc2 = e2.getAttribute("schemaLocation");
						if (loc1 != null && !loc1.isEmpty() && loc2 != null && !loc2.isEmpty()) {
