    Schema s = ReflectData.get().getSchema(DocTest.class);
    String actualJson = s.toString();

    // Normalize actualJson to ignore non-deterministic field order
    int aFieldsStart = actualJson.indexOf("\"fields\":[") + 9;
    int aFieldsEnd = actualJson.lastIndexOf("]}");
    String aFieldsContent = actualJson.substring(aFieldsStart, aFieldsEnd);
    List<String> aFields = new ArrayList<>();
    int depth = 0;
    int currentStart = 0;
    for (int i = 0; i < aFieldsContent.length(); i++) {
        char c = aFieldsContent.charAt(i);
        if (c == '{') {
            if (depth == 0) currentStart = i;
            depth++;
        } else if (c == '}') {
            depth--;
            if (depth == 0) {
                aFields.add(aFieldsContent.substring(currentStart, i + 1));
            }
        }
    }
    aFields.sort(Comparator.comparing(str -> {
        int ns = str.indexOf("\"name\":\"") + 8;
        int ne = str.indexOf("\"", ns);
        return str.substring(ns, ne);
    }));
    StringBuilder aSb = new StringBuilder();
    for (int i = 0; i < aFields.size(); i++) {
        if (i > 0) aSb.append(",");
        aSb.append(aFields.get(i));
    }
    String normalizedActual = actualJson.substring(0, aFieldsStart) + aSb.toString() + actualJson.substring(aFieldsEnd);

    // Normalize expectedJson in the exact same way
    int eFieldsStart = expectedJson.indexOf("\"fields\":[") + 9;
    int eFieldsEnd = expectedJson.lastIndexOf("]}");
    String eFieldsContent = expectedJson.substring(eFieldsStart, eFieldsEnd);
    List<String> eFields = new ArrayList<>();
    depth = 0;
    currentStart = 0;
    for (int i = 0; i < eFieldsContent.length(); i++) {
        char c = eFieldsContent.charAt(i);
        if (c == '{') {
            if (depth == 0) currentStart = i;
            depth++;
        } else if (c == '}') {
            depth--;
            if (depth == 0) {
                eFields.add(eFieldsContent.substring(currentStart, i + 1));
            }
        }
    }
    eFields.sort(Comparator.comparing(str -> {
        int ns = str.indexOf("\"name\":\"") + 8;
        int ne = str.indexOf("\"", ns);
        return str.substring(ns, ne);
    }));
    StringBuilder eSb = new StringBuilder();
    for (int i = 0; i < eFields.size(); i++) {
        if (i > 0) eSb.append(",");
        eSb.append(eFields.get(i));
    }
    String normalizedExpected = expectedJson.substring(0, eFieldsStart) + eSb.toString() + expectedJson.substring(eFieldsEnd);

    assertEquals(normalizedExpected, normalizedActual);
  }

