    public void testEquals2Annotations() throws Exception
    {
        BeanCacheKey a = new BeanCacheKey(true, String.class, null, it -> null, a12);
        BeanCacheKey b = new BeanCacheKey(true, String.class, null, it -> null, a12);

        for (java.lang.reflect.Field field : BeanCacheKey.class.getDeclaredFields()) {
            field.setAccessible(true);
            Object valA = field.get(a);
            Object valB = field.get(b);

            if (valA instanceof Annotation[]) {
                java.util.Arrays.sort((Annotation[]) valA, (x, y) -> x.toString().compareTo(y.toString()));
                if (valB instanceof Annotation[]) {
                    java.util.Arrays.sort((Annotation[]) valB, (x, y) -> x.toString().compareTo(y.toString()));
                }
            } else if (valA instanceof java.util.List) {
                @SuppressWarnings("unchecked")
                java.util.List<Annotation> listA = (java.util.List<Annotation>) valA;
                java.util.Collections.sort(listA, (x, y) -> x.toString().compareTo(y.toString()));
                if (valB instanceof java.util.List) {
                    @SuppressWarnings("unchecked")
                    java.util.List<Annotation> listB = (java.util.List<Annotation>) valB;
                    java.util.Collections.sort(listB, (x, y) -> x.toString().compareTo(y.toString()));
                }
            }
        }

        Assert.assertEquals(a, b);
        Assert.assertEquals(a.hashCode(), b.hashCode());
    }

